effect.frag.content:
uniform float u_amount;
const float TAU = 6.28318530718;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return texture(u_source, uv);
}
mat2 rotation(float a) { float c = cos(a), s = sin(a); return mat2(c, -s, s, c); }
vec4 over(vec4 front, vec4 back) { return front + back * (1.0 - front.a); }
void main() {
  vec4 color = vec4(0.0);
  for (int i = 0; i < 3; i++) {
    float angle = TAU * (u_progress + float(i) / 3.0);
    vec2 p = rotation(TAU * u_progress) * (v_uv - 0.5 - vec2(cos(angle), sin(angle)) * (0.16 + u_amount * 0.12));
    vec4 c = length(p) < 0.2 ? sourceAt(p / 0.4 + 0.5) : vec4(0.0);
    color = over(c, color);
  }
  fragColor = color;
}
